-- ============================================================
-- SalesPlace — مستهدفات شاشة المبيعات الحيّة (جدول خاص بالداشبورد)
-- جدول جديد + دالة قراءة جديدة — لا يمسّ أي جدول أو دالة موجودة حالياً
-- شغّل هذا الملف كاملاً مرة واحدة في Supabase SQL editor (آمن لإعادة التشغيل)
-- ============================================================
-- المصادر:
--  • NHC: الملف الماستر لمذكرات الاستثمار، ورقة «الخطة بالسنوات»، صف «الوحدات المباعة» —
--    53 مشروعاً، مستهدف سنوي بالوحدات لكل مشروع (2022–2033). المدينة والكود من ورقة «لوحة المحفظة».
--  • المطورون: الملف الماستر لا يحوي أي مستهدف للمطورين. مؤقتاً تُنسخ من خطة المبيعات
--    الموجودة بالتطبيق (جدول sales_targets، developer_kind = 'مطورين') مجموعةً سنوياً لكل مشروع،
--    وتُستبدل متى توفّر مصدر معتمد لمستهدفات المطورين.

create table if not exists dashboard_targets (
  id bigint generated always as identity primary key,
  scope text not null check (scope in ('nhc','dev')),
  project_name text not null,
  project_code text,
  sector text,
  city text,
  year integer not null,
  units numeric not null default 0,
  revenue numeric,
  source text not null,
  updated_at timestamptz not null default now(),
  unique (scope, project_name, year)
);
create index if not exists dashboard_targets_year_idx on dashboard_targets(year, scope, sector);

alter table dashboard_targets enable row level security;
drop policy if exists dashboard_targets_read on dashboard_targets;
create policy dashboard_targets_read on dashboard_targets for select using (true);

-- NHC من مذكرات الاستثمار (170 صفاً: مشروع × سنة بمبيعات مخطّطة)
delete from dashboard_targets where scope = 'nhc';

-- المطورون — مؤقتاً من خطة المبيعات بالتطبيق (sales_targets)، مجموع الأشهر لكل مشروع وسنة
delete from dashboard_targets where scope = 'dev';
select 'dev', project_name, max(project_code), max(sector), null, year, sum(target), null,
       'مؤقت: خطة المبيعات بالتطبيق (sales_targets، مطورين) — المذكرات لا تحوي مستهدفات للمطورين'
from sales_targets
where developer_kind = 'مطورين'
group by project_name, year
having sum(target) > 0;

-- مستهدف سنة معيّنة مجمّعاً: لكل نطاق (nhc/dev) الإجمالي والتفصيل حسب القطاع وعدد المشاريع والمصدر
create or replace function get_dashboard_targets(p_year int)
returns jsonb
language sql
stable
security definer
set search_path to 'public'
as $$
  with s as (
    select scope, coalesce(sector,'غير محدد') as sector, sum(units) as u, max(source) as src
    from dashboard_targets where year = p_year
    group by scope, coalesce(sector,'غير محدد')
  ),
  sc as (
    select scope, sum(u) as total, max(src) as source, jsonb_object_agg(sector, u) as by_sector
    from s group by scope
  ),
  pc as (
    select scope, count(distinct project_name) as projects
    from dashboard_targets where year = p_year group by scope
  )
  select jsonb_build_object(
    'ok', true, 'year', p_year,
    'scopes', coalesce((
      select jsonb_object_agg(sc.scope, jsonb_build_object(
        'total', sc.total, 'projects', pc.projects, 'source', sc.source, 'by_sector', sc.by_sector))
      from sc join pc using (scope)
    ), '{}'::jsonb)
  );
$$;
